def skill():
    tot = 0
    for m in range(2, 11):
        f = factorint(m)
        for n in range(2, 11):
            e = Rational(6, n) if n % 2 else Rational(12, n)
            if all((a*e).q == 1 for a in f.values()):
                tot += 1
    return tot

def prod_real(m, n):
    x = Symbol('x')
    p = Integer(1)
    for r in real_roots(x**n - Integer(m)**6):
        p *= r
    return nsimplify(p)

def standard():
    return sum(1 for m in range(2, 11) for n in range(2, 11) if prod_real(m, n).is_integer)

def unique():
    return [standard()]
